func TestSIRAXBT72xxExampleParsesWithConfirmedDCScaling(t *testing.T) {
	got, err := Load("../../configs/modbus-sirax-bt72xx.example.yaml", false)
	if err != nil {
		t.Fatalf("SIRAX example configuration: %v", err)
	}
	if len(got.Sources) != 1 || got.Sources[0].Name != "sirax-dc" || got.Sources[0].Driver != "modbus_rtu" || got.Sources[0].ModbusRTU == nil {
		t.Fatalf("SIRAX sources=%+v", got.Sources)
	}
	modbus := got.Sources[0].ModbusRTU
	want := []struct {
		name     string
		address  uint16
		dataType string
		scale    float64
		unit     string
	}{
		{"status", 71, "uint16", 1, ""},
		{"voltage", 72, "float32", 1, "V"},
		{"current", 74, "float32", -0.0001, "A"},
		{"power_active", 76, "float32", -0.1, "W"},
		{"power_reactive", 78, "float32", -0.1, "var"},
		{"power_apparent", 80, "float32", -0.1, "VA"},
		{"power_factor", 82, "float32", 1, ""},
		{"frequency", 84, "float32", 1, "Hz"},
		{"thd", 86, "float32", 1, ""},
		{"energy_total", 88, "float32", 0.1, "kWh"},
		{"energy_positive", 90, "float32", 0.1, "kWh"},
		{"energy_negative", 92, "float32", 0.1, "kWh"},
	}
	if len(modbus.Registers) != len(want) || modbus.SlaveID != 1 || modbus.BaudRate != 9600 || modbus.DataBits != 8 || modbus.Parity != "N" || modbus.StopBits != 1 {
		t.Fatalf("SIRAX Modbus settings=%+v", modbus)
	}
	for index, expected := range want {
		register := modbus.Registers[index]
		if register.Name != expected.name || register.Address != expected.address || register.Type != expected.dataType || register.Unit != expected.unit || register.Function != 3 || register.WordOrder != "low_high" || register.ByteOrder != "big" || register.Scale != expected.scale || register.Offset != 0 {
			t.Errorf("register[%d]=%+v, want name=%q address=%d type=%q unit=%q function=3 word_order=low_high byte_order=big scale=%v offset=0", index, register, expected.name, expected.address, expected.dataType, expected.unit, expected.scale)
		}
	}
}

// TestReadSecretRejectsUnsafeFilesAndContent verifies no-follow, regular-file, size, and control-character safeguards.
func TestReadSecretRejectsUnsafeFilesAndContent(t *testing.T) {
	d := t.TempDir()
	regular := filepath.Join(d, "regular")
	if err := os.WriteFile(regular, []byte("safe-secret-value\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(d, "link")
	if err := os.Symlink(regular, link); err != nil {
		t.Fatal(err)
	}
	if _, err := readSecret(link); err == nil {
		t.Fatal("symlink accepted")
	}
	large := filepath.Join(d, "large")
	if err := os.WriteFile(large, []byte(strings.Repeat("x", 4097)), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := readSecret(large); err == nil {
		t.Fatal("oversized secret accepted")
	}
	control := filepath.Join(d, "control")
	if err := os.WriteFile(control, []byte("valid-prefix\nsecond-line"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := readSecret(control); err == nil {
		t.Fatal("embedded control accepted")
	}
	fifo := filepath.Join(d, "fifo")
	if err := syscall.Mkfifo(fifo, 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := readSecret(fifo); err == nil {
		t.Fatal("non-regular secret accepted")
	}
}

// TestLoadFilesDeepMergesMappingsAndReplacesLists verifies ordered configuration layering.
func TestLoadFilesDeepMergesMappingsAndReplacesLists(t *testing.T) {
	directory := t.TempDir()
	token := writeSecret(t, directory, "token", "layered-token-value")
	basePath := filepath.Join(directory, "base.yaml")
	overlayPath := filepath.Join(directory, "site.yaml")
	base := baseYAML([]string{token}, []string{"127.0.0.1"}) + `
sources:
  - name: base-ups
    driver: nut
    poll_interval: 10s
    stale_after: 20s
    timeout: 2s
    nut:
      server: 127.0.0.1:3493
      ups: base
logging:
  level: info
`
	overlay := `authentication:
  allowed_clients:
    - "2001:db8::/64"
sources:
  - name: site-ups
    driver: nut
    poll_interval: 15s
    stale_after: 30s
    timeout: 3s
    nut:
      server: "127.0.0.1:3493"
      ups: site
logging:
  level: debug
`
	if err := os.WriteFile(basePath, []byte(base), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(overlayPath, []byte(overlay), 0o600); err != nil {
		t.Fatal(err)
	}
	loaded, err := LoadFiles([]string{basePath, overlayPath}, true)
	if err != nil {
		t.Fatal(err)
	}
	if loaded.Logging.Level != "debug" || len(loaded.Sources) != 1 || loaded.Sources[0].Name != "site-ups" {
		t.Fatalf("merged config=%+v", loaded)
	}
	if len(loaded.Secrets.BearerTokens) != 1 || len(loaded.Secrets.AllowedClients) != 1 || loaded.Secrets.AllowedClients[0] != netip.MustParsePrefix("2001:db8::/64") {
		t.Fatalf("merged secrets=%+v", loaded.Secrets)
	}
}

